input.command:
cd /Users/michelkerkmeester/worktrees/public/315-frontend-reference-restructure/.skilled/skills/system-spec-kit/references/workflows && python3 - <<'EOF'
import re
files = ["goal-set-string-playbook.md","intake-contract.md","nested-changelog.md","quick-reference.md","rename-pattern.md","spec-authoring-card.md","spec-folder-authoring-checklist.md","spec-folder-write-recipe.md"]
for f in files:
    lines = open(f).read().split("\n")
    in_code = False
    print("=====",f)
    start=None; buf=[]
    for i,l in enumerate(lines,1):
        if l.startswith("```"):
            in_code = not in_code
            continue
        if in_code: continue
        s=l.strip()
        is_text = s and not s.startswith(("#","-","|",">","*","1.","2.","3.","4.","5.","6.","7.","8.","9.","0.","[")) and not re.match(r"^\d+\.",s)
        if is_text:
            if start is None: start=i; buf=[]
            buf.append(s)
        else:
            if start is not None:
                text=" ".join(buf)
                n=len(re.findall(r"[.!?](\s|$)",text))
                if n>=3:
                    print(f"{start}-{i-1} sentences~{n}: {text[:160]}...")
                start=None
    if start is not None:
        text=" ".join(buf); n=len(re.findall(r"[.!?](\s|$)",text))
        if n>=3: print(f"{start}-{len(lines)} sentences~{n}: {text[:160]}...")
EOF

